import json, traceback, sys
print('Starting build_trajectory_index for OH...')
sys.stdout.flush()
try:
    index = {}
    with open('/root/autodl-tmp/openhands_data/openhands_trajectories.jsonl') as f:
        for row_idx, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            raw = json.loads(line)
            steps = []
            for s in raw.get('trajectory') or []:
                steps.append({
                    'role': s.get('role', 'unknown'),
                    'text': s.get('text') or s.get('system_prompt') or '',
                })
            index[row_idx] = steps
            if (row_idx + 1) % 500 == 0:
                print(f'  Loaded {row_idx+1} trajectories')
                sys.stdout.flush()
    print(f'Done: {len(index)} trajectories loaded')
except Exception as e:
    traceback.print_exc()
